<?php require_once __DIR__.'/../src/db.php';$db=db();$panos=$db->query("SELECT * FROM panoramas WHERE published=1 ORDER BY id DESC")->fetchAll();$tours=$db->query("SELECT t.*,(SELECT COUNT(*) FROM tour_scenes s WHERE s.tour_id=t.id) scene_count,(SELECT COALESCE(p.preview,p.image) FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=t.id ORDER BY CASE WHEN s.id=t.start_scene_id THEN 0 ELSE 1 END,s.sort_order,s.id LIMIT 1) fallback_cover FROM tours t WHERE t.published=1 ORDER BY t.id DESC")->fetchAll();?>
